            J[(bra * 10 + 2)] = Jp2;
            J[(bra * 10 + 3)] = Jp3;
            J[(bra * 10 + 4)] = Jp4;
            J[(bra * 10 + 5)] = Jp5;
            J[(bra * 10 + 6)] = Jp6;
            J[(bra * 10 + 7)] = Jp7;
            J[(bra * 10 + 8)] = Jp8;
            J[(bra * 10 + 9)] = Jp9;
        }
    }
}
